// Shape of the reference generated by scripts/type-reference.mjs and served by type-reference-plugin.mjs
// (ticket #402). Keep in sync with the extractor (REFERENCE_VERSION).
declare module 'virtual:formrail/type-reference' {
  export interface ReferenceMember {
    name: string;
    /** As written in the source (one line). */
    type: string;
    optional: boolean;
    /** From `@default` or from "Default `x`" in the prose. */
    default?: string;
    /** Markdown. */
    description: string;
    deprecated?: string;
    examples?: string[];
    /** A public type the member is declared in, when it is not the entry itself. */
    inheritedFrom?: string;
    /** Repo-relative `path:line`. */
    source?: string;
    /** Function parameters only. */
    rest?: boolean;
  }

  export interface ReferenceVariant {
    title: string;
    /** Required members of the branch, when the branch has no name of its own. */
    requires?: string[];
    members: ReferenceMember[];
  }

  export interface ReferenceSignature {
    signature: string;
    typeParameters: string[];
    parameters: ReferenceMember[];
    returns: { type: string; description: string };
  }

  interface ReferenceEntryBase {
    name: string;
    package: string;
    description: string;
    deprecated?: string;
    examples?: string[];
    source: string;
  }

  export interface ReferenceTypeEntry extends ReferenceEntryBase {
    kind: 'interface' | 'type';
    typeParameters: string[];
    /** Members (for a union: the ones every branch shares). */
    members?: ReferenceMember[];
    /** A union of object types: one section per branch, with the members only that branch has. */
    variants?: ReferenceVariant[];
    /** Non-object branches of a union (`null`). */
    otherVariants?: string[];
    /** Bases whose `@types/react` members (HTML/DOM attributes) are not listed. */
    inherits?: string[];
    /** A type with no members (union of literals, function type): its definition. */
    definition?: string;
  }

  export interface ReferenceFunctionEntry extends ReferenceEntryBase {
    kind: 'function';
    signatures: ReferenceSignature[];
  }

  export type ReferenceEntry = ReferenceTypeEntry | ReferenceFunctionEntry;

  export interface TypeReferenceData {
    version: number;
    entries: Record<string, ReferenceEntry>;
  }

  const reference: TypeReferenceData;
  export default reference;
}
